head.script:
/**
 * 전역 변수
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.svrcertLoadYn = 'N';
scwin.title = '인증서로 검색';


/**
 * 화면 pageload 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.onpageload = function() {

    ssgo.setDocumentTitle(scwin.title);

    //공지사항
    tit_ntc.hide();
    grd_ntcLst.hide();

    // anySign plugin 체크
    scwin.ufn_loadAnySignPluginCheck( function(){  
        
        // 세션스토리지에 공지사항 내용이 존재하면 DB조회 안함.
        var storage = ssgo.STORAGE.NTC_INFO;
        if(!scutilo.isEmpty(ssgo.getSessionStorage(storage.ID, storage.KIND.ntcInfo))) {
            dma_search.set("isNtcLst", "Y");   // 공지사항 세션스토리지 존재여부
        }
        // 로그인 정보 조회 submission 실행
        com.executeSubmission(sbm_costLgnMyCs);
    });

    // 3. 각 검색영역별 enter event add
    ssgo.setEnterKeyEventOfGrpObj(grp_rrno, scwin.btnAuthChk_onclick, "input secret" );

};

/**
 * 화면 pageunload 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.onpageunload = function() {
};


/**
 *********************************************************************************************************
 * Submission Event Handler
 *********************************************************************************************************
 */
/**
 * ID 로그인 정보 조회 submission done 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.01.20.   최연구       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbm_costLgnMyCs_submitdone = function(res) {
    var dma_idLgn = res.responseJSON.data.dma_idLgn;
    scwin.isLocal = dma_idLgn.isLocal;
    
    // SSO로그인 여부
    var isSso = dma_idLgn.isSso;
    if(isSso == "Y") {
        var param = {
                     "initYn" : "Y", 
                     "isSso" : isSso,
                     "ssoUserNm" : dma_idLgn.ssoUserNm,
                     };
        com.win.moveUrl(ssgo.getCtxtPathUrl(ssgo.getProperties("clt.ssgo.mycs.lst")), param);
        return false;
    }

    // 서버 인증서
    scwin.svrcert = dma_idLgn.svrcert;
    if(!scutilo.isEmpty(scwin.svrcert)) {
        scwin.svrcertLoadYn = 'Y';
    }
    
    // 주민번호입력란 비활성화
    ibx_btprtRrno1.focus();

    //세션스토리지에 공지사항 내용이 존재하면 DB조회 안함.
    var storage = ssgo.STORAGE.NTC_INFO;
    var ntcList = ssgo.getSessionStorage(storage.ID, storage.KIND.ntcInfo);
    if(!scutilo.isEmpty(ntcList)) {
        dlt_ntcList.removeAll();
        dlt_ntcList.setJSON(JSON.parse(ntcList));
    } else {
        if(dlt_ntcList.getRowCount() > 0) {
            ssgo.removeSessionStorageSection(storage.ID);
            ssgo.setSessionStorage(storage.ID, storage.KIND.ntcInfo, JSON.stringify(dlt_ntcList.getAllJSON()));
        }
    }
    
    //공지사항 영역제어
    if(dlt_ntcList.getRowCount() > 0) {
        tit_ntc.show("");
        grd_ntcLst.show("");
    } 
    

};

/**
 * 인증서검증 submission done 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.01.20.   최연구       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbm_pblcCertfVrfc_submitdone = function(e) {

    var resultData = e.responseJSON;
    try {
        if (resultData.status == 200) {
            var param = {initYn : "Y"};
            com.win.moveUrl(ssgo.getCtxtPathUrl(ssgo.getProperties("clt.ssgo.mycs.lst")), param);
        }
    } catch (ex) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.W_0104), function () { //W_0104 : 서버 통신 도중 오류가 발생하였습니다. 잠시후 다시 시도해주시기 바랍니다.
        });
    }
};


/**
 * 인증서검증 submission error 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_pblcCertfVrfc_submiterror = function(e) {
    ssgo.printSubmiterror(e);
};

/**
 *********************************************************************************************************
 * Event Handler
 *********************************************************************************************************
 */

scwin.btnAuthChk_onclick = function(e) {

    // if(scwin.isLocal == "Y") {
    //     // 주민번호
    //     var btprtRrno = ibx_btprtRrno1.getValue() + ibx_btprtRrno2.getValue();
    //     dma_lgnUser.set("btprtRrno", btprtRrno);
    //     com.executeSubmission(sbm_pblcCertfVrfc);
    //     return false;
    // }
    
    // 정합성 체크
    if(!scwin.vfn_validateCsSrch()) {
        return false;
    }

    if(scwin.svrcertLoadYn == 'N') {
        scutilo.showMsg(scglblo.MSG.INFO, "인증서 서버 설정이 준비되지 않았습니다.\n몇초후 다시 시도 해주시기 바랍니다.", function() {
            
            var focusTime = setInterval(function() {

                ibx_btprtRrno1.focus();
                clearTimeout(focusTime);
            }, 100);
        });
        return false;
    }

    if(scutilo.isEmpty(scwin.svrcert)) {
        scutilo.showMsg(scglblo.MSG.INFO, "인증서 서버 설정이 되어 있지 않습니다.", function() {
            
            var focusTime = setInterval(function() {

                ibx_btprtRrno1.focus();
                clearTimeout(focusTime);
            }, 100);
        });
        return false;        
    }
    else {
        // 서버에서 전달해주는 서버 인증서 정보가 javascript 선언부까지 들어가있어서 eval 사용
        eval(scwin.svrcert);

        // 서버에서 전달받은 값이 빈값이면
        if(scutilo.isEmpty(svrcert)) {
            svrcert = '';
            svrcert += '-----BEGIN CERTIFICATE-----\n';
            svrcert += '-----END CERTIFICATE-----\n';
            svrcert += '';
        }
        var btprtRrno = ibx_btprtRrno1.getValue() + ibx_btprtRrno2.getValue();
        var flg = true;
        var signed_data, envValue;

        // clearCache를 하지 않으면 캐쉬의 값을 사용하므로
        // 인증서 선택창이 뜨지 않는다.
        //ClearCache();
        console.log("@@@ scwin.btn_certfLgn_onclick Sign_without_vid_web-->", Sign_without_vid_web);
        console.log("@@@ scwin.btn_certfLgn_onclick svrcert-->", svrcert);
        
        // 인증서 서명
        Sign_without_vid_web(4194304 , 
                            'login', 
                            svrcert , 
                            btprtRrno , 
                            function(signedData) {
                                send_vid_info(function(envValue){
                                    console.log("@@@ scwin.btn_certfLgn_onclick signedData-->", signedData);
                                    console.log("@@@ scwin.btn_certfLgn_onclick envValue-->", envValue);
                                    // 서명값
                                    dma_lgnUser.set("signedData", signedData);
                                    // VID값
                                    dma_lgnUser.set("envData", envValue);
                                    // 주민번호
                                    dma_lgnUser.set("btprtRrno", btprtRrno);

                                    com.executeSubmission(sbm_pblcCertfVrfc);
                                });
                            },
                            scwin.aErrorCallback);
        return true;
    }
};

/**
 * 인증서 실패 callback
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.01.20.   최연구       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.aErrorCallback = function(aResult) {
    console.log("@@@ aErrorCallback arguments-->", arguments);
    var aError = aResult.msg + "[Error Code=" + aResult.code + "]";
    scutilo.showMsg(scglblo.MSG.INFO, "Sign_without_vid_web error!!!\n" + aError, function () {
    });

    ClearCache();

    if (aResult.code != -1201 && aResult.code != 128) {
        //XecureWebError();
        flg = false;
        // return false;
    } else
        flg = false;
        // return false;

        focus();
        return false;
}

/**
 * 플러그인 설치 확인 에러 이벤트용 함수
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.01.20.   최연구       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btnAnysignDownLoad_onclick = function(e) {
    ssgo.sendPostForm(ssgo.getCtxtPathUrl("/installPlugin.on"), $p.parent().scwin.topParam);
};

/**
 * 지원OS확인하기 클릭 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.01.20.   최연구       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btnOsIdnty_onclick = function(e) {

    requires("uiplugin.popup");

    var data = {};
    var options = {
        "id" : "osIdntyPopup",
        "type" : "window",
        "width" : "1200px",
        "height" : "810px",
        "popupName" : "지원 가능한 브라우저 및 OS 확인",
        "menubar" : false,
        "modal" : false,
        "resizable": true
    };

    $p.openPopup(ssgo.getCtxtPathUrl("/ui/ssgo10l/SSGO10LP03.xml"), options, data);

};

/**
 *********************************************************************************************************
 * Validate 
 *********************************************************************************************************
 */

/**
 * 사건검색 검색조건 정합성 체크
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.vfn_validateCsSrch = function() {

    var btprtRrno1  = ibx_btprtRrno1.getValue();
    var btprtRrno2  = ibx_btprtRrno2.getValue();

    if(scutilo.isEmpty(btprtRrno1) || btprtRrno1.length != 6) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0001, "주민번호를"), function() {   //I_0001: "주민번호를 입력하십시오."
            
            var focusTime = setInterval(function() {

                ibx_btprtRrno1.focus();
                clearTimeout(focusTime);
            }, 100);
        });
        return false; 
    }

    if(scutilo.isEmpty(btprtRrno2) || btprtRrno2.length != 7) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0001, "주민번호를"), function() {   //I_0001: "주민번호를 입력하십시오."
            
            var focusTime = setInterval(function() {

                ibx_btprtRrno2.focus();
                clearTimeout(focusTime);
            }, 100);
        });
        return false; 
    }

    return true;
}


/**
 *********************************************************************************************************
 * User Function
 *********************************************************************************************************
 */

    
/**
 * anySign plugin 체크 
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.01.20.   최연구       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ufn_loadAnySignPluginCheck = function(callbackFunc) {
    var flg = true;
    do {
        // 프로세스바 노출
        WebSquare.layer.showProcessMessage("anySign 파일 로드중입니다.");
        
        AnySignLoad.init( function() {
            
            // 설치 여부 검증 처리                 
            AnySign.mAnySignShowImg.showImg = false;
            AnySign.StartAnySign(true);


            setTimeout(function(){
                AnySign4PC_installCheck( function(r){
                    console.log('anySign: ',r);                    
                    if(r === 'ANYSIGN4PC_NORMAL'){
                        callbackFunc();
                    }else{
                        // 플러그인 설치 확인 에러 처리
                        scwin.ufn_chkInstlPluginError();
                    }
                    // 프로세스바 숨김
                    WebSquare.layer.hideProcessMessage();                     
                });
            },500);
        });
    } while (!flg) {
    }
}; 

/**
 * 플러그인 설치 확인 에러 이벤트용 함수
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.01.20.   최연구       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ufn_chkInstlPluginError = function() {

    scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0104), function() { //I_0104: "설치가 필요한 프로그램이 있습니다.\n설치페이지로 이동합니다."
        location.href = ssgo.getCtxtPathUrl("/installPlugin.on");
    });
    
    return false;
}
